qlgstack *qlgstack_push(qlgstack *s, void *elem) {
    if (!s) {
        return NULL;
    }
    struct node *n = malloc(sizeof(struct node));
    if (!n) {
        return NULL;
    }
    n->elem = elem;          // store the address, not a copy of the element
    n->next = s->top;
    s->top = n;
    s->size++;
    return s;
}

qlgstack *qlgstack_pop(qlgstack *s, void **popped) {
    if (!s) {
        return NULL;
    }
    struct node *oldtop = s->top;
    void *elem = oldtop->elem;
    s->top = oldtop->next;
    s->size--;
    free(oldtop);            // the NODE is freed, the element is not
    if (popped) {
        *popped = elem;      // give the element's address to the caller
    }
    return s;
}

#include <stdio.h>
#include <stdlib.h>
#include "qlgstack.h"

void print_double(const void *elem) {
    const double *d = elem;
    printf("%.1f", *d);
}

void free_double(void *elem) {
    free(elem);
}

int main(void) {
    qlgstack *s = qlgstack_new();
    if (!s) {
        fprintf(stderr, "out of memory\n");
        return 1;
    }
    for (int i = 1; i <= 3; i++) {
        double *d = malloc(sizeof(double));   // each element gets its own heap object
        if (!d) {
            fprintf(stderr, "out of memory\n");
            qlgstack_free(s, free_double);
            return 1;
        }
        *d = i * 1.5;
        qlgstack_push(s, d);                  // the stack stores the pointer d
    }
    qlgstack_print("s: ", s, "\n", print_double);

    void *p;                                  // pop writes a void * here
    qlgstack_pop(s, &p);
    double *top = p;                          // convert, then use
    printf("popped %.1f\n", *top);
    free(top);                                // popped: the caller frees it now

    qlgstack_print("s: ", s, "\n", print_double);
    qlgstack_free(s, free_double);            // frees the nodes AND the 2 doubles left
    return 0;
}

