#include <stdio.h>

void print_int(const void *elem) {
    const int *p = elem;      // convert elem to pointer to int
    printf("%d", *p);
}

void print_double(const void *elem) {
    const double *p = elem;   // convert elem to pointer to double
    printf("%f", *p);
}

void print_string(const void *elem) {
    const char *p = elem;     // convert elem to pointer to char
    printf("%s", p);
}

int main(void) {
    // ptr2func can point at any function like: void f(const void *elem)
    void (*ptr2func)(const void *elem) = NULL;

    int x = 1;
    ptr2func = &print_int;
    (*ptr2func)(&x);
    printf("\n");

    double y = -99.9;
    ptr2func = &print_double;
    (*ptr2func)(&y);
    printf("\n");

    char str[] = "CISC220";
    ptr2func = print_string;      // & is optional
    ptr2func(str);                // so is the *
    printf("\n");
    return 0;
}

#include <stdio.h>

typedef void (*print_func)(const void *elem);

void print_char(const void *elem) {
    const char *c = elem;
    printf("'%c'", *c);
}

void print_long(const void *elem) {
    const long *n = elem;
    printf("%ldL", *n);
}

// calls f on each of the count objects whose addresses are in elems
void print_all(void *elems[], size_t count, print_func f) {
    for (size_t i = 0; i < count; i++) {
        f(elems[i]);
        printf(" ");
    }
    printf("\n");
}

int main(void) {
    char a = 'Q', b = 'u';
    long big = 1234567890123L, small = -8;
    void *chars[] = {&a, &b};
    void *longs[] = {&big, &small};
    print_all(chars, 2, print_char);
    print_all(longs, 2, print_long);
    return 0;
}

void qlgstack_free(qlgstack *s, qlgstack_free_func ptr) {
    if (!s) {
        return;
    }
    // free all nodes
    struct node *n = s->top;
    while (n) {
        struct node *next = n->next;
        if (ptr) {
            ptr(n->elem);           // deallocate memory used by the element
        }
        free(n);
        n = next;
    }
    // free the stack
    free(s);
}

#include <stdio.h>
#include <stdlib.h>
#include "qlgstack.h"

void print_string(const void *elem) {
    const char *str = elem;
    printf("%s", str);
}

int main(int argc, char *argv[]) {
    qlgstack *s = qlgstack_new();
    if (!s) {
        fprintf(stderr, "out of memory\n");
        return 1;
    }
    for (int i = 1; i < argc; i++) {
        qlgstack_push(s, argv[i]);   // argv[i] already points at a string
    }
    qlgstack_print("", s, "\n", print_string);
    qlgstack_free(s, NULL);          // NULL: do NOT free the elements
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "qlgstack.h"

struct student {
    char *name;      // points at its own heap copy of the name
    int mark;
};

// Returns a new heap student holding a copy of name, or NULL.
struct student *student_new(const char *name, int mark) {
    struct student *st = malloc(sizeof(struct student));
    if (!st) {
        return NULL;
    }
    st->name = malloc(strlen(name) + 1);
    if (!st->name) {
        free(st);
        return NULL;
    }
    strcpy(st->name, name);
    st->mark = mark;
    return st;
}

void print_student(const void *elem) {
    const struct student *st = elem;
    printf("%s(%d)", st->name, st->mark);
}

void free_student(void *elem) {
    struct student *st = elem;
    free(st->name);      // first the name inside...
    free(st);            // ...then the struct itself
}

int main(void) {
    qlgstack *s = qlgstack_new();
    if (!s) {
        return 1;
    }
    qlgstack_push(s, student_new("Ada", 91));
    qlgstack_push(s, student_new("Linus", 78));
    qlgstack_push(s, student_new("Grace", 85));
    qlgstack_print("", s, "\n", print_student);
    qlgstack_free(s, free_student);
    return 0;
}

