#include <stdio.h>
#include <stdlib.h>

struct node {
    int elem;
    struct node *next;
};

// Adds a new node holding elem in front of head; returns the new head.
struct node *add_front(struct node *head, int elem) {
    struct node *n = malloc(sizeof(struct node));
    if (!n) {
        fprintf(stderr, "out of memory\n");
        exit(EXIT_FAILURE);
    }
    n->elem = elem;
    n->next = head;
    return n;
}

void print_list(const struct node *head) {
    printf("[");
    for (const struct node *n = head; n; n = n->next) {
        printf("%d", n->elem);
        if (n->next) {
            printf(",");
        }
    }
    printf("]\n");
}

// Removes the first node holding target and frees it.
// Returns the (possibly new) head of the list.
struct node *remove_first(struct node *head, int target) {
    struct node *prev = NULL;      // the node before cur (none yet)
    struct node *cur = head;
    while (cur && cur->elem != target) {
        prev = cur;                // walk: prev follows one step behind cur
        cur = cur->next;
    }
    if (!cur) {                    // reached the end: target not in the list
        return head;
    }
    if (!prev) {                   // cur is the head: no node before it
        head = cur->next;
    } else {                       // middle or last node: bypass cur
        prev->next = cur->next;
    }
    free(cur);                     // unlink FIRST, free LAST
    return head;
}

void free_list(struct node *head) {
    while (head) {
        struct node *next = head->next;   // save the link before freeing
        free(head);
        head = next;
    }
}

int main(void) {
    struct node *list = NULL;
    for (int v = 50; v >= 10; v -= 10) {
        list = add_front(list, v);
    }
    print_list(list);
    list = remove_first(list, 30);     // middle
    print_list(list);
    list = remove_first(list, 10);     // head
    print_list(list);
    list = remove_first(list, 50);     // last
    print_list(list);
    list = remove_first(list, 99);     // not there
    print_list(list);
    free_list(list);
    return 0;
}

