#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "qlgstack.h"

void print_string(const void *elem) {
    const char *str = elem;
    printf("%s", str);
}

void free_string(void *elem) {
    free(elem);
}

int main(void) {
    const char *words[] = {"ant", "bee", "cat"};
    qlgstack *s = qlgstack_new();
    if (!s) {
        return 1;
    }
    for (int i = 0; i < 3; i++) {
        char *copy = malloc(strlen(words[i]) + 1);
        if (!copy) {
            qlgstack_free(s, free_string);
            return 1;
        }
        strcpy(copy, words[i]);
        qlgstack_push(s, copy);
    }
    qlgstack_print("before: ", s, "\n", print_string);

    void *p;
    qlgstack_pop(s, &p);
    char *top = p;
    printf("popped %s\n", top);
    free(top);

    qlgstack_print("after: ", s, "\n", print_string);
    qlgstack_free(s, free_string);
    return 0;
}

// Deletes the last node of list and returns the number it held.
// If list is empty or has only one node, does nothing and returns 0.
int deleteLast(LinkedList list) {
    if (list == NULL || list->next == NULL) {
        return 0;
    }
    struct ListNode *prev = list;          // the node before cur
    struct ListNode *cur = list->next;     // at least 2 nodes, so cur is not NULL
    while (cur->next != NULL) {            // stop when cur is the last node
        prev = cur;
        cur = cur->next;
    }
    int val = cur->data;                   // save the data BEFORE freeing
    prev->next = NULL;                     // prev becomes the new last node
    free(cur);
    return val;
}
